const empresasActivasIA = `-- name: EmpresasActivasIA :many
SELECT coalesce(a.empresa_id, 0)::bigint AS empresa_id, coalesce(e.nombre, '')::text AS nombre
FROM mensajeria.asistente_ajustes a LEFT JOIN nucleo.empresas e ON e.id = a.empresa_id
WHERE a.proveedor = 'servidor_ia' AND a.activo ORDER BY 1
`

type EmpresasActivasIARow struct {
	EmpresaID int64
	Nombre    string
}

// Empresas cuyo asistente está encendido con el servidor de IA (plaza garantizada, tablero).
func (q *Queries) EmpresasActivasIA(ctx context.Context) ([]EmpresasActivasIARow, error) {
	rows, err := q.db.Query(ctx, empresasActivasIA)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []EmpresasActivasIARow
	for rows.Next() {
		var i EmpresasActivasIARow
		if err := rows.Scan(&i.EmpresaID, &i.Nombre); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

