const sumarUsoIA = `-- name: SumarUsoIA :exec
UPDATE mensajeria.servidor_ia_uso SET peticiones = peticiones + $1, tokens_entrada = tokens_entrada + $2,
    tokens_salida = tokens_salida + $3, latencia_ms_suma = latencia_ms_suma + $4,
    latencia_cubetas = (SELECT array_agg(c.v + CASE WHEN c.i = $5::int THEN 1 ELSE 0 END ORDER BY c.i)
                        FROM unnest(latencia_cubetas) WITH ORDINALITY AS c (v, i)),
    rechazos = rechazos + $6,
    errores = CASE WHEN $7::text = '' THEN errores
                   ELSE jsonb_set(errores, ARRAY[$7::text], to_jsonb(coalesce((errores ->> $7::text)::bigint, 0) + 1)) END
WHERE motor_id = $8 AND hora = $9 AND empresa_id = $10 AND modelo = $11
`

type SumarUsoIAParams struct {
	Peticiones    int64
	TokensEntrada int64
	TokensSalida  int64
	LatenciaMs    int64
	Cubeta        int32
	Rechazos      int64
	Motivo        string
	MotorID       int64
	Hora          time.Time
	EmpresaID     int64
	Modelo        string
}

func (q *Queries) SumarUsoIA(ctx context.Context, arg SumarUsoIAParams) error {
	_, err := q.db.Exec(ctx, sumarUsoIA,
		arg.Peticiones,
		arg.TokensEntrada,
		arg.TokensSalida,
		arg.LatenciaMs,
		arg.Cubeta,
		arg.Rechazos,
		arg.Motivo,
		arg.MotorID,
		arg.Hora,
		arg.EmpresaID,
		arg.Modelo,
	)
	return err
}

